    public static readonly NamePool Fallback = new(
        new[] { "Leo", "Marco", "Nico", "Alex", "Daniel", "Luca", "Samir", "Jonas", "Andre", "Milan", "Rafael", "Yannick" },
        new[] { "Costa", "Silva", "Moreau", "Keller", "Rossi", "Novak", "Hansen", "Petrov", "Almeida", "Fischer", "Lopes", "Mendes" });

    public static NamePool Pool(string code) => Pools.TryGetValue(code, out var pool) ? pool : Fallback;
}
